window.SBL_LESSONS['HD-t1-l1-measuring-human'] = {
  id: 'HD-t1-l1-measuring-human',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'Measuring human development',
  href: '/geography/paper-2/hl-2/t1-development/l1-measuring-human',
  syllabusFocus: 'The multidimensional process of human development and ways to measure it: UN Sustainable Development Goals (SDG) criteria, and the validity and reliability of development indicators and indices, including the Human Development Index (HDI) and Gender Inequality Index (GII).',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is human development?', request: 'Explain the multidimensional process of human development' },
    { label: 'The Sustainable Development Goals', request: 'Explain the UN Sustainable Development Goals (SDGs) as a way of measuring development' },
    { label: 'The Human Development Index', request: 'Explain what the Human Development Index (HDI) measures and how it is calculated' },
    { label: 'The Gender Inequality Index', request: 'Explain what the Gender Inequality Index (GII) measures' },
    { label: 'Validity and reliability', request: 'Explain what validity and reliability mean in the context of development indicators' },
    { label: 'Comparing composite indicators', request: 'Compare the effectiveness of the SDGs, HDI and GII as ways of measuring development' },
    { label: 'Help me evaluate an indicator', request: 'Help me practise writing an evaluation of a development indicator using terms like validity, composite and multi-dimensional' }
  ],
  checklist: [
    'I can identify a variety of ways in which development can be measured and evaluate them.',
    'I can compare the effectiveness of three composite human development indicators \u2014 the SDGs, HDI and GII.',
    'I can use terms such as validity, composite, multi-dimensional and equality when making an evaluation.'
  ],
  readinessQuestions: [
    'Why is human development described as "multidimensional"?',
    'What is the Human Development Index (HDI), and what does it combine?',
    'What is the Gender Inequality Index (GII) designed to measure?',
    'What is the difference between validity and reliability when evaluating a development indicator?',
    'What is one strength and one limitation of using a composite indicator like the HDI?'
  ],
  quiz: [
    { q: 'Human development is described as "multidimensional" because it:', options: ['Is measured mainly by GDP per capita, which captures all aspects of wellbeing', 'Involves several linked dimensions of wellbeing, such as health, education and income', 'Develops in fixed stages that every country passes through in the same order', 'Depends only on access to basic needs such as food, water and shelter, which shows that income matters less than health'], correct: 1, explain: 'Human development is described as multidimensional because it involves multiple interconnected dimensions of wellbeing \u2014 such as health, education and income \u2014 rather than being captured by a single economic factor alone.', misconception: 'Development is sometimes reduced to just "how rich a country is," when the multidimensional concept recognises that health, education and other factors are equally important.', tag: 'What is human development?' },
    { q: 'The UN Sustainable Development Goals (SDGs) are best described as:', options: ['Eight global goals focused mainly on halving extreme poverty by 2015, later expanded to include targets for climate', '17 interconnected global goals with social, economic and environmental targets for 2030', 'A composite index ranking countries by health, education and income', 'A legally binding treaty that sets emissions targets for each country'], correct: 1, explain: 'The SDGs are a set of 17 interconnected global goals, adopted by the United Nations, covering a wide range of social, economic and environmental targets that countries are encouraged to work towards by 2030.', misconception: 'The SDGs are sometimes assumed to be a single composite score like the HDI, when they are actually a broader framework of 17 distinct goals covering many different aspects of development.', tag: 'The Sustainable Development Goals' },
    { q: 'The Human Development Index (HDI) combines indicators relating to:', options: ['Life expectancy, adult literacy and GDP per capita at market exchange rates', 'Life expectancy, years of schooling (expected and mean) and GNI per capita', 'Infant mortality, access to clean water and GNI per capita', 'Maternal mortality, school enrolment and household income'], correct: 1, explain: 'The HDI combines three dimensions: life expectancy at birth (health), education (expected and mean years of schooling), and gross national income (GNI) per capita, producing a composite score that reflects development more broadly than income alone.', misconception: 'The HDI is sometimes assumed to be based purely on income, when it specifically combines health and education indicators alongside income to give a more rounded picture of development.', tag: 'The Human Development Index' },
    { q: 'The Gender Inequality Index (GII) measures inequality between men and women across which dimensions?', options: ['Life expectancy, education and income per capita for each sex, compared with a male baseline', 'Reproductive health, empowerment and labour-market participation', 'Literacy, income and access to healthcare for women only', 'Political rights, civil liberties and freedom of the press'], correct: 1, explain: 'The GII measures gender-based inequality across three dimensions: reproductive health, empowerment (such as parliamentary representation and secondary education attainment), and labour market participation.', misconception: 'The GII is sometimes confused with simply measuring the number of women in a population, when it actually measures inequality of outcomes and opportunities between men and women across several dimensions.', tag: 'The Gender Inequality Index' },
    { q: 'A GII score closer to 0 indicates:', options: ['Greater inequality between men and women', 'Greater equality between men and women', 'A higher level of human development overall', 'Lower female participation in the labour market'], correct: 1, explain: 'On the GII scale, a score closer to 0 indicates greater equality between men and women across the measured dimensions, while a score closer to 1 indicates greater inequality.', misconception: 'It is worth double-checking the direction of any index rather than assuming; for the GII specifically, a lower score is generally the more favourable outcome, representing less inequality.', tag: 'The Gender Inequality Index' },
    { q: 'Validity, as it relates to a development indicator, refers to:', options: ['Whether an indicator gives the same result each time it is measured', 'Whether an indicator actually measures what it claims to measure', 'Whether the data are collected regularly by an official agency', 'Whether an indicator can be compared across many countries'], correct: 1, explain: 'Validity refers to whether an indicator genuinely measures what it claims to measure \u2014 for example, whether GNI per capita is a valid measure of overall "development" or only captures the economic dimension.', misconception: 'Validity and reliability are sometimes used interchangeably, but validity specifically concerns whether the indicator measures the right thing, while reliability concerns consistency of measurement.', tag: 'Validity and reliability' },
    { q: 'Reliability, as it relates to a development indicator, refers to:', options: ['Whether an indicator measures the concept it claims to measure', 'Whether an indicator gives consistent results when measured the same way', 'Whether an indicator includes several dimensions of development', 'Whether an indicator is accepted by international organisations, such as the UN or the World Bank'], correct: 1, explain: 'Reliability refers to whether an indicator produces consistent, repeatable results when measured using the same method \u2014 for example, whether life expectancy data is collected and calculated consistently across different countries and years.', misconception: 'Reliability is sometimes confused with accuracy or validity; reliability specifically concerns the consistency of the measurement process itself, separate from whether it measures the "right" concept.', tag: 'Validity and reliability' },
    { q: 'A composite indicator, such as the HDI, is one that:', options: ['Uses a single statistic that directly measures one aspect of life', 'Combines several individual indicators into one overall score', 'Compares one country\u2019s data against the world average', 'Measures the change in one indicator over a period of time'], correct: 1, explain: 'A composite indicator, such as the HDI, combines multiple individual indicators (like life expectancy, education and income) into a single overall score or index, aiming to provide a more rounded measure than any single statistic alone.', misconception: 'A single overall number is sometimes assumed to be a "simple" indicator, when a composite indicator like the HDI is actually the product of combining several underlying measures together.', tag: 'Comparing composite indicators' },
    { q: 'A key limitation shared by composite indicators like the HDI and GII is that they:', options: ['Rely on a single variable, so they ignore social aspects of development', 'Combine several factors into one score, which can hide variation within a country', 'Can only be calculated for high-income countries with good data, so they exclude most of the world', 'Are revised so often that comparisons over time are impossible'], correct: 1, explain: 'A key limitation of composite indicators like the HDI and GII is that combining multiple factors into a single score can mask important variation \u2014 a country might score well overall while performing poorly on one specific underlying dimension, or while hiding significant inequality within the country.', misconception: 'A composite score is sometimes treated as a complete, unambiguous picture, when it is important to also examine the underlying component indicators to understand what is really driving the overall score.', tag: 'Comparing composite indicators' },
    { q: 'When evaluating the effectiveness of the SDGs, HDI and GII together as ways of measuring development, geographers would consider that:', options: ['The HDI alone is enough, as it already includes gender and sustainability', 'Each captures a different aspect, so together they give a fuller but imperfect picture', 'The SDGs replace the need for indices because they measure progress directly, so indices are no longer needed', 'The GII is the most valid, as gender inequality drives all other gaps'], correct: 1, explain: 'A strong evaluation recognises that the SDGs (a broad goal framework), HDI (a composite of health/education/income) and GII (a composite of gender-based inequality) each capture a different aspect of development, so considering them together gives a more complete picture, while also acknowledging that each has its own specific limitations around validity and reliability.', misconception: 'Evaluation is sometimes reduced to simply naming a limitation of one indicator, when a stronger response compares strengths and weaknesses across multiple indicators and considers how using them together can offset individual limitations.', tag: 'Comparing composite indicators' }
  ]
};

window.SBL_LESSONS['HD-t1-l2-empowering'] = {
  id: 'HD-t1-l2-empowering',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'Empowering women, indigenous and minority groups',
  href: '/geography/paper-2/hl-2/t1-development/l2-empowering',
  syllabusFocus: 'Detailed illustrative examples of affirmative action to close the development gap, including affirmative action to promote gender equality for women in Nepal, action supporting LGBTQ+ communities as a minority group, and the impact of outside influences and affirmative action on the Dani people of Irian Jaya.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is affirmative action?', request: 'Define affirmative action and give examples as it pertains to minority groups' },
    { label: 'Women in Nepal', request: 'Explain how affirmative action in Nepal has helped bring about greater gender equality' },
    { label: 'LGBTQ+ affirmative action', request: 'Explain a basic example of affirmative action supporting LGBTQ+ communities as a minority group' },
    { label: 'The Dani people of Irian Jaya', request: 'Explain how the Dani people of Irian Jaya have been impacted by outside influences' },
    { label: 'Affirmative action for the Dani', request: 'Describe the affirmative action taken by Christian missionaries and the Indonesian government regarding the Dani people' },
    { label: 'Why affirmative action is used', request: 'Explain why governments and organisations use affirmative action to close the development gap' },
    { label: 'Evaluating affirmative action', request: 'Help me evaluate the effectiveness of affirmative action as a strategy' }
  ],
  checklist: [
    'I can define and give examples of \u2018affirmative action\u2019 as it pertains to minority groups.',
    'I can describe how affirmative action in Nepal can help bring about greater gender equality.',
    'I can identify how the Dani people of Irian Jaya have been impacted by outside influences and describe the affirmative action taken by Christian missionaries and the Indonesian government.'
  ],
  ibQuestions: [
    {
      question: 'Using examples, analyse how affirmative action can be used to close the development gap.',
      marks: 12,
      markScheme:
        'Marked as a levels-based extended answer (Level 1: 1–4 marks, Level 2: 5–8 marks, Level 3: 9–12 marks). Level 1 answers show only a basic, partial understanding of affirmative action, use at most one simple example, are mostly descriptive, and make weak links to the development gap. Level 2 answers show a good understanding of affirmative action, use at least two relevant named examples, explain how the strategy works, offer some analysis of its impact on development including some discussion of successes and limitations, and use geographical terminology accurately. Level 3 answers give detailed analysis throughout, use three or more well-developed named examples, make strong and specific links to the development gap, offer a balanced evaluation of effectiveness, reach a well-supported judgement, and are organised in a clear, logically flowing structure with a conclusion. Indicative content — the following examples are not prescriptive; other relevant, well-explained affirmative action examples must also be credited: girls’ education programmes in Nepal, improving female literacy and access to employment and income; schools established for the Dani people in Indonesia (e.g. by missionaries), improving literacy, numeracy and participation in the wider economy, alongside government infrastructure, transport and solar electricity programmes for Dani communities — though poverty and low educational progression often remain, and some traditional cultural practices have declined; political quota systems in Rwanda giving women a high proportion of parliamentary seats, increasing their voice in decisions affecting education, healthcare and employment; and anti-discrimination and equal-opportunity employment legislation supporting LGBTQ communities in some countries, improving access to jobs and legal protection — though this protection and its effectiveness vary widely and discrimination continues in many places. The strongest answers evaluate effectiveness on both sides, recognising that affirmative action can meaningfully close aspects of the development gap while also creating unintended consequences (e.g. pressure on traditional culture and identity) or leaving some inequalities unresolved, and conclude that affirmative action is most effective when combined with wider development strategies that address the underlying causes of inequality.'
    }
  ],
  readinessQuestions: [
    'What is affirmative action, and who might it be aimed at?',
    'What is one example of affirmative action supporting gender equality for women in Nepal?',
    'What is one example of affirmative action supporting LGBTQ+ communities as a minority group?',
    'Who are the Dani people, and how have they been impacted by outside influences?',
    'What affirmative action has been taken in relation to the Dani people, by whom?'
  ],
  quiz: [
    { q: 'Affirmative action, as it pertains to minority groups, refers to:', options: ['Equal treatment for everyone, with no special measures for any group', 'Targeted policies that improve opportunities for groups that have faced discrimination', 'Aid from high-income countries given directly to minority groups, administered through NGOs', 'Laws that require minority groups to adopt the majority culture'], correct: 1, explain: 'Affirmative action refers to deliberate policies or measures aimed at improving opportunities and reducing inequality for groups that have historically faced discrimination or disadvantage, such as women, indigenous peoples, or other minority groups.', misconception: 'Affirmative action is sometimes assumed to be a single specific policy, when it actually describes a broad category of deliberate measures that can take many different forms depending on the group and context.', tag: 'What is affirmative action?' },
    { q: 'Affirmative action to promote gender equality for women in Nepal has included measures such as:', options: ['Banning child marriage, which removed the need for political quotas, introduced across the whole country', 'Reserved seats for women in politics, plus improved access to education', 'Equal pay laws that apply only to government employees', 'Free university places for women living in Kathmandu'], correct: 1, explain: 'Affirmative action in Nepal supporting gender equality has included measures such as reserved seats or quotas for women in political representation, alongside initiatives aimed at improving women\u2019s access to education and economic opportunity.', misconception: 'Gender equality initiatives are sometimes assumed to happen automatically as a country develops, when specific, deliberate affirmative action policies (like reserved political seats) have been a key mechanism driving change in Nepal.', tag: 'Women in Nepal' },
    { q: 'A basic example of affirmative action supporting LGBTQ+ communities as a minority group would be:', options: ['Quotas guaranteeing LGBTQ+ people a set share of parliamentary seats, similar to the quotas used for women', 'Anti-discrimination laws protecting LGBTQ+ people at work or in legal recognition', 'Funding separate schools and services for LGBTQ+ communities', 'Removing questions about identity from national censuses'], correct: 1, explain: 'A basic example of affirmative action supporting LGBTQ+ communities includes introducing anti-discrimination laws or policies that specifically protect LGBTQ+ individuals, such as employment protections or legal recognition of same-sex relationships, aiming to reduce disadvantage faced by this minority group.', misconception: 'Affirmative action is sometimes thought of only in terms of gender or ethnicity, when it can apply to a range of minority groups, including those defined by sexual orientation or gender identity.', tag: 'LGBTQ+ affirmative action' },
    { q: 'The Dani people are an indigenous group located in:', options: ['The highlands of Papua New Guinea, east of the Indonesian border', 'Irian Jaya (Papua), the Indonesian part of the island of New Guinea', 'Kalimantan, the Indonesian part of the island of Borneo, close to the Malaysian border', 'The northern mountains of Thailand near the Myanmar border'], correct: 1, explain: 'The Dani are an indigenous people located in the highlands of Irian Jaya, the Indonesian-administered western half of the island of New Guinea.', misconception: 'The specific location of the Dani people is sometimes uncertain to students; they are specifically an indigenous group of the Irian Jaya highlands in Indonesia.', tag: 'The Dani people of Irian Jaya' },
    { q: 'Outside influences that have impacted the Dani people have historically included:', options: ['Mainly tourism developers and conservation NGOs, with little state role', 'Christian missionaries and Indonesian government integration policies', 'Mainly Chinese traders, with little religious or state influence', 'Mainly palm oil companies clearing highland forests'], correct: 1, explain: 'Outside influences on the Dani people have historically included contact with Christian missionaries, who introduced new religious beliefs, alongside integration efforts by the Indonesian government, both of which have brought significant cultural, economic and social change to traditional Dani ways of life.', misconception: 'Outside influence on indigenous groups is sometimes assumed to be a single simple process, when it typically involves multiple actors (such as religious missionaries and government bodies) each bringing distinct forms of change.', tag: 'The Dani people of Irian Jaya' },
    { q: 'Affirmative action taken by Christian missionaries in relation to the Dani people has typically included:', options: ['Protecting traditional practices by limiting all outside contact, as missionaries wanted to preserve the culture', 'Setting up schools, healthcare and religious education, while changing some traditions', 'Funding Dani land-rights claims against the Indonesian government', 'Running political campaigns for Papuan independence'], correct: 1, explain: 'Christian missionaries working with the Dani people have typically taken actions such as establishing schools and providing healthcare, alongside religious education, while also promoting changes to some traditional practices, as part of broader efforts to support development alongside religious conversion.', misconception: 'Missionary influence is sometimes considered only in religious terms, when it has often also included practical affirmative action such as establishing schools and healthcare services.', tag: 'Affirmative action for the Dani' },
    { q: 'Affirmative action taken by the Indonesian government in relation to the Dani people has typically included:', options: ['Granting the Dani full autonomy to govern their own territory, with a separate parliament', 'Integration policies, infrastructure and bringing the Dani into national education', 'Protecting Dani land as a closed reserve with no outside access', 'Leaving development entirely to missionaries and NGOs'], correct: 1, explain: 'The Indonesian government has pursued integration policies towards the Dani people, including infrastructure development and efforts to bring the Dani into the wider Indonesian education and economic system, as part of national development strategy for the Irian Jaya region.', misconception: 'Government affirmative action towards indigenous groups is sometimes assumed to be purely protective in nature, when in the case of the Dani, government policy has also actively pursued integration into the wider national system, which itself has both benefits and disadvantages worth evaluating.', tag: 'Affirmative action for the Dani' },
    { q: 'A general reason governments and organisations use affirmative action to close the development gap is that:', options: ['Economic growth alone spreads benefits evenly to every group, without any need for targeted policy', 'Disadvantaged groups face structural barriers, so targeted policies are needed', 'Minority groups usually choose not to take part in development', 'International law requires every country to use quotas'], correct: 1, explain: 'Affirmative action is used because historically disadvantaged groups often face structural barriers (such as discrimination, limited access to education, or exclusion from political processes) that prevent equal access to opportunities, meaning deliberate, targeted policies are often needed to help close the resulting development gap.', misconception: 'Development gaps are sometimes assumed to close naturally over time without intervention, when geographers recognise that structural barriers often persist unless deliberately addressed through targeted policy.', tag: 'Why affirmative action is used' },
    { q: 'A challenge sometimes associated with affirmative action policies, worth considering in an evaluation, is that they:', options: ['They cannot be measured, so their effects are unknown', 'They can create resentment among groups who feel disadvantaged by them', 'They are illegal under international human rights law, so they cannot be enforced', 'They only work in high-income countries with strong institutions'], correct: 1, explain: 'A genuine evaluative point is that affirmative action policies can sometimes generate debate or resistance, including from groups who feel they are disadvantaged by the policy, even while the policy aims to reduce inequality for a different, historically disadvantaged group \u2014 this tension is a recognised part of evaluating such policies.', misconception: 'Affirmative action is sometimes presented as universally accepted and uncontroversial, when a stronger evaluation recognises that such policies can generate genuine debate, which is worth acknowledging even while explaining their intended benefits.', tag: 'Evaluating affirmative action' },
    { q: 'Comparing the Nepal, LGBTQ+, and Dani examples of affirmative action together illustrates that:', options: ['Political quotas are always the most effective form of it', 'It takes different forms depending on the group and context', 'It works best when imposed by outside organisations', 'It is only needed in low-income countries, where inequality is greatest'], correct: 1, explain: 'Comparing these three examples together illustrates that affirmative action can take many different forms depending on the specific group and context \u2014 from political quotas (Nepal), to anti-discrimination law (LGBTQ+ communities), to missionary and government-led integration efforts (the Dani) \u2014 showing the breadth of what this concept can encompass.', misconception: 'It is sometimes assumed affirmative action always looks the same, when comparing multiple real-world examples together shows how varied the specific mechanisms and actors involved can be.', tag: 'What is affirmative action?' }
  ]
};

window.SBL_LESSONS['HD-t1-l3-the-importance'] = {
  id: 'HD-t1-l3-the-importance',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'The importance of social entrepreneurship for human development \u2014 micro-finance and \u2018Fairtrade\u2019',
  href: '/geography/paper-2/hl-2/t1-development/l3-the-importance',
  syllabusFocus: 'The importance of social entrepreneurship approaches for human development, including micro-finance schemes and Fairtrade, using illustrative examples such as the Grameen Bank, Kiva and KickStart.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is social entrepreneurship?', request: 'Define social entrepreneurship and explain how it differs from ordinary entrepreneurship' },
    { label: 'What is micro-finance?', request: 'Explain what micro-finance is and how it supports human development' },
    { label: 'The Grameen Bank', request: 'Explain the Grameen Bank as an example of a micro-finance social enterprise' },
    { label: 'Kiva', request: 'Explain how Kiva works as a micro-finance social enterprise' },
    { label: 'KickStart', request: 'Explain how KickStart works as a social enterprise' },
    { label: 'What is Fairtrade?', request: 'Explain what Fairtrade is and how it supports human development' },
    { label: 'Evaluating social entrepreneurship', request: 'Help me evaluate the importance of social entrepreneurship for human development' }
  ],
  checklist: [
    'I can define what social entrepreneurship is and how it differs from ordinary entrepreneurship.',
    'I can explain how micro-finance schemes, such as the Grameen Bank and Kiva, support human development.',
    'I can explain how Fairtrade supports human development.'
  ],
  ibQuestions: [
    {
      question: "Explain how microfinance organisations and alternative trading networks can help communities to develop. [May 2021, Paper 3, Q1(a)]",
      marks: 12,
      markScheme: "A strong response explains how microfinance (small loans and savings, often to women, such as Grameen Bank or Kiva) and alternative trading networks (such as Fairtrade) increase incomes, empower marginalised groups and support community investment, with named examples. It recognises limitations such as debt, high interest rates and the small scale of change. Mark holistically out of 12: reward detailed, accurate knowledge, clear analysis linked to the question and well-chosen named examples."
    }
  ],
  readinessQuestions: [
    'What is the key difference between an ordinary entrepreneur and a social entrepreneur?',
    'What is micro-finance, and how does it aim to support development?',
    'What is the Grameen Bank, and what is it known for?',
    'How does Kiva work as a micro-finance platform?',
    'What is Fairtrade, and how does it aim to support producers in developing countries?'
  ],
  quiz: [
    { q: 'A social entrepreneur is best defined as someone who:', options: ['Runs a profitable business and donates a share of profits to charity', 'Uses business methods to run a venture that tackles a social problem', 'Works for a government agency that delivers social services', 'Founds a charity that relies entirely on donations and grants'], correct: 1, explain: 'A social entrepreneur recognises a social problem and uses entrepreneurial principles \u2014 such as innovation, risk-taking and business strategy \u2014 to organise, create and manage a venture that drives social change, rather than purely pursuing financial profit.', misconception: 'Social entrepreneurship is sometimes confused with simple charitable giving; a social entrepreneur specifically runs a venture using business methods to achieve social goals, which is a distinct approach from donating to an existing charity.', tag: 'What is social entrepreneurship?' },
    { q: 'A key difference between an ordinary entrepreneurial venture and a social entrepreneurial venture is that:', options: ['Ordinary ventures aim for profit; social ventures measure success by social impact', 'Social ventures cannot make a profit, while ordinary ventures must, as profits must be given away', 'Ordinary ventures are private, while social ventures are run by governments', 'Social ventures can only operate in low-income countries'], correct: 0, explain: 'Ordinary entrepreneurial ventures primarily aim to serve markets with new products or services for financial gain, while social entrepreneurial ventures aim to drive social change using business solutions, measuring success through sustainability and social impact rather than profit alone.', misconception: 'It is sometimes assumed social ventures cannot generate any revenue, when many social enterprises do generate income \u2014 the key distinction is that profits are reinvested towards the social mission rather than distributed purely for private financial gain.', tag: 'What is social entrepreneurship?' },
    { q: 'Micro-finance is best defined as:', options: ['Large development loans from the World Bank to national governments, mainly for large projects', 'Small loans, savings and financial services for people without access to banks', 'Interest-free loans given only to registered businesses', 'Grants from NGOs that recipients do not have to repay'], correct: 1, explain: 'Micro-finance refers to small loans, savings accounts, and other financial services provided to individuals or small businesses, often in low-income communities, who typically lack access to traditional banking services, aiming to support entrepreneurship and reduce poverty.', misconception: 'Micro-finance is sometimes confused with traditional large-scale bank lending; the defining feature is specifically small-scale loans aimed at those excluded from conventional banking, often without requiring traditional collateral.', tag: 'What is micro-finance?' },
    { q: 'The Grameen Bank, founded by Muhammad Yunus, is significant as an example of micro-finance because it:', options: ['Was the first bank to offer mobile-phone money transfers', 'Pioneered small, collateral-free loans to very poor people, mainly women', 'Provides large loans to governments for infrastructure projects', 'Gives grants rather than loans so borrowers avoid debt, so that borrowers never fall into debt'], correct: 1, explain: 'The Grameen Bank, founded by Muhammad Yunus, pioneered providing small, collateral-free "micro-loans" to some of the poorest individuals, particularly aimed at helping them start or grow their own income-generating activities as a route out of extreme poverty.', misconception: 'Traditional banking typically requires collateral to secure a loan; the Grameen Bank\u2019s significance lies partly in demonstrating that collateral-free lending to very poor borrowers could still be a viable and effective model.', tag: 'The Grameen Bank' },
    { q: 'Kiva operates as a micro-finance platform by:', options: ['Lending only its own capital to farmers through local bank branches', 'Letting individuals worldwide lend small sums online to entrepreneurs', 'Donating products to communities instead of lending money, chosen by village leaders', 'Allowing small businesses to sell shares to investors online'], correct: 1, explain: 'Kiva allows regular individuals ("investors") around the world to provide small loans to small business owners in developing countries via the internet, with lenders able to track the progress of the business they have supported, and repaid funds becoming "Kiva Credit" that can be used to fund further loans.', misconception: 'Kiva is sometimes assumed to be a traditional charity that simply gives away money, when its specific model is based on facilitating peer-to-peer loans (which are generally repaid), distinguishing it from a pure donation-based charity.', tag: 'Kiva' },
    { q: 'KickStart is an example of a social enterprise that focuses on:', options: ['Giving start-up grants to young people in urban slums', 'Designing affordable technology, such as irrigation pumps, for small enterprises', 'Providing small loans to women through local savings groups, through a network of savings groups', 'Certifying farm products so producers receive a fair price'], correct: 1, explain: 'KickStart, founded by Martin Fisher and Nick Moon, focuses on promoting sustainable growth and employment creation in developing countries by developing technologies (such as low-cost irrigation pumps) that local entrepreneurs can use to establish and run their own small-scale enterprises.', misconception: 'KickStart is sometimes assumed to directly hand out finished products for free, when its model is centred on providing accessible technology that enables local entrepreneurs to build sustainable businesses themselves.', tag: 'KickStart' },
    { q: 'Fairtrade is best defined as a certification and movement that aims to:', options: ['Consumers in high-income countries pay the lowest possible prices, because supermarkets set fair prices', 'Producers in developing countries get a fairer price and better trading conditions', 'Farmers sell only to local markets, avoiding global trade', 'Governments set fixed prices for agricultural exports'], correct: 1, explain: 'Fairtrade is a certification and movement that aims to ensure producers, particularly in developing countries, receive a fairer price and improved trading conditions for goods such as coffee, cocoa or tea, helping support more stable incomes and improved development outcomes for producer communities.', misconception: 'Fairtrade is sometimes assumed to simply be a marketing label with no real economic mechanism behind it, when it specifically involves minimum price guarantees and trading standards designed to directly benefit producers.', tag: 'What is Fairtrade?' },
    { q: 'A company combining corporate social responsibility with a product like Fairtrade coffee (as with the Starbucks example) illustrates that:', options: ['Any company that sells Fairtrade products is a social enterprise, whatever its other business practices', 'CSR by a large company is different from a dedicated social enterprise', 'Fairtrade certification turns a TNC into a non-profit organisation', 'CSR schemes and social enterprises are legally the same thing'], correct: 1, explain: 'A company emphasising corporate social responsibility (CSR), such as a large coffee chain sourcing Fairtrade coffee, is considered a distinct concept from being a dedicated social enterprise \u2014 a social enterprise has social impact as its core defining purpose, while a company\u2019s CSR initiative is one part of a broader business primarily focused on other goals.', misconception: 'CSR initiatives and social enterprises are sometimes treated as identical, when geographers distinguish between a company doing socially responsible things alongside its main business (CSR) and a venture whose core mission is specifically social change (a social enterprise).', tag: 'Evaluating social entrepreneurship' },
    { q: 'A recognised benefit of micro-finance and Fairtrade approaches for human development is that they:', options: ['Guarantee that participants escape poverty within a few years, without needing any other support', 'Provide income and opportunity for people without banks or fair prices', 'Replace the need for government spending on development', 'Mainly benefit consumers through lower prices'], correct: 1, explain: 'A recognised benefit of both micro-finance and Fairtrade is that they can provide direct economic opportunities and improved income stability for individuals and communities who may otherwise lack access to traditional financial systems (in the case of micro-finance) or fair market prices for their goods (in the case of Fairtrade).', misconception: 'Micro-finance and Fairtrade are sometimes treated as the same mechanism, when they operate quite differently \u2014 one provides access to credit/finance, the other guarantees fairer trading terms for goods \u2014 even though both aim to support similar development outcomes.', tag: 'Evaluating social entrepreneurship' },
    { q: 'When evaluating the overall importance of social entrepreneurship approaches like micro-finance and Fairtrade for human development, geographers would consider:', options: ['Mainly the number of people reached, since scale shows success, as this shows real impact', 'Both the benefits and limitations, such as small scale or debt risk', 'Mainly the profits made, since sustainability depends on them', 'Only the views of consumers who buy Fairtrade products'], correct: 1, explain: 'A strong evaluation of social entrepreneurship approaches considers both genuine benefits (such as improved income, opportunity and market access) alongside potential limitations (such as the limited overall scale of many schemes, or the risk of debt for micro-finance borrowers who struggle to repay), rather than presenting these approaches as either wholly positive or wholly ineffective.', misconception: 'Evaluation is sometimes reduced to simply listing positive outcomes, when geographers are expected to weigh up both the genuine strengths and the real limitations of any development approach, including social entrepreneurship.', tag: 'Evaluating social entrepreneurship' }
  ]
};

window.SBL_LESSONS['HD-t1-l4-tncs-and'] = {
  id: 'HD-t1-l4-tncs-and',
  topicNumber: 1,
  topicTitle: 'Development opportunities',
  title: 'TNCs and Corporate Social Responsibility',
  href: '/geography/paper-2/hl-2/t1-development/l4-tncs-and',
  syllabusFocus: 'The importance of social entrepreneurship approaches for human development: TNC corporate social responsibility frameworks and global agreements, and the increasing level of global interdependence and the need for sustainable development.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is CSR?', request: 'Define Corporate Social Responsibility (CSR)' },
    { label: 'IKEA and sustainability', request: 'Explain how IKEA can make progress towards sustainability as an example of a TNC and CSR' },
    { label: 'International Framework Agreements', request: 'Explain what International Framework Agreements (IFAs) are and give examples' },
    { label: 'How IFAs support development', request: 'Explain how International Framework Agreements can contribute to human development' },
    { label: 'Global interdependence', request: 'Explain the increasing level of global interdependence between countries and companies' },
    { label: 'The need for sustainable development', request: 'Explain why global interdependence creates a need for sustainable development' },
    { label: 'Evaluating CSR', request: 'Help me evaluate the effectiveness of CSR as a strategy for human development' }
  ],
  checklist: [
    'I can define Corporate Social Responsibility (CSR).',
    'I can make reference to IKEA in describing how a TNC can make progress towards sustainability.',
    'I can give examples of International Framework Agreements (IFAs) and describe how they can contribute to human development.'
  ],
  readinessQuestions: [
    'What is Corporate Social Responsibility (CSR)?',
    'How does IKEA illustrate a TNC making progress towards sustainability?',
    'What is an International Framework Agreement (IFA)?',
    'How can IFAs contribute to human development?',
    'Why does increasing global interdependence create a need for sustainable development?'
  ],
  quiz: [
    { q: 'Corporate Social Responsibility (CSR) is best defined as:', options: ['The legal minimum standards that every company must follow, enforced by national governments', 'A company\u2019s voluntary commitment to manage its social and environmental impacts', 'A tax paid by TNCs to fund development in host countries', 'A company\u2019s duty to maximise returns for its shareholders'], correct: 1, explain: 'Corporate Social Responsibility refers to a company\u2019s voluntary commitment to operate in ways that consider its social, environmental and economic impacts, often going beyond the minimum legal requirements, and can include areas such as sustainable sourcing, labour standards, and community investment.', misconception: 'CSR is sometimes assumed to be a strict legal obligation, when it more accurately describes voluntary commitments that can vary significantly in genuine impact and ambition between different companies.', tag: 'What is CSR?' },
    { q: 'IKEA is used as an example of a TNC making progress towards sustainability partly because it has:', options: ['Moving all production back to Sweden to cut transport emissions, which it completed in the last decade', 'Sourcing sustainable materials, investing in renewables and setting emissions targets', 'Stopping the sale of flat-pack furniture to reduce packaging', 'Replacing all its wood products with recycled plastic'], correct: 1, explain: 'IKEA is used as a CSR/sustainability example because it has pursued initiatives such as sourcing more sustainable materials (like FSC-certified wood), investing in renewable energy for its stores and operations, and setting targets to reduce emissions and waste across its global supply chain.', misconception: 'Large TNCs are sometimes assumed to have no genuine sustainability commitments, when companies like IKEA have made specific, trackable commitments across their supply chains, even though the overall effectiveness and pace of such commitments remains a legitimate topic for evaluation.', tag: 'IKEA and sustainability' },
    { q: 'An International Framework Agreement (IFA) is best defined as:', options: ['A trade agreement between countries reducing tariffs on manufactured goods', 'An agreement between a TNC and a global union setting labour standards', 'A code of conduct written by a TNC without union involvement', 'A UN treaty making labour standards legally binding everywhere'], correct: 1, explain: 'An International Framework Agreement (IFA) is a formal agreement, typically negotiated between a TNC and a global trade union federation, setting minimum labour and social standards that are intended to apply consistently across the company\u2019s international operations and supply chain.', misconception: 'IFAs are sometimes confused with ordinary national labour laws; their distinctive feature is that they are negotiated specifically to apply consistent standards across a TNC\u2019s multiple international operations, rather than being tied to a single country\u2019s legal system.', tag: 'International Framework Agreements' },
    { q: 'IFAs can contribute to human development because they:', options: ['Raising wages to the same level in every country where the TNC operates, so that workers everywhere earn the same', 'Setting minimum labour standards across a TNC, even where national laws are weak', 'Replacing national labour laws with company rules', 'Giving host governments control over TNC supply chains'], correct: 1, explain: 'IFAs can contribute to human development by helping establish consistent minimum labour and social standards \u2014 such as fair wages, safe working conditions, and the right to unionise \u2014 across a TNC\u2019s global operations, including in countries where national labour protections may otherwise be weaker.', misconception: 'The potential development impact of IFAs is sometimes overlooked, when consistent labour standards across a TNC\u2019s international supply chain can have a meaningful effect on working conditions and rights for large numbers of workers in developing countries.', tag: 'How IFAs support development' },
    { q: 'Global interdependence, as it relates to TNCs and CSR, refers to:', options: ['Countries becoming more self-sufficient as trade grows, so they depend less on one another', 'Countries, companies and supply chains increasingly relying on one another', 'TNCs controlling the economic policies of host governments', 'Companies relying mainly on suppliers in their home country'], correct: 1, explain: 'Global interdependence refers to the increasing degree to which countries, companies and supply chains are interconnected and reliant on one another across the world, meaning decisions and standards set by a TNC in one location can have significant effects on workers, communities and environments elsewhere.', misconception: 'Global interdependence is sometimes discussed only in terms of trade flows, when it also has direct relevance to how TNC behaviour (including CSR commitments) in one location can affect development outcomes in very different parts of the world.', tag: 'Global interdependence' },
    { q: 'The increasing level of global interdependence creates a need for sustainable development partly because:', options: ['Actions in one place can have social, economic or environmental effects elsewhere', 'Trade automatically spreads environmental standards to every country, so governments need not act', 'Interdependence means only global institutions can take action', 'Countries must reduce trade in order to protect the environment'], correct: 0, explain: 'Because countries, companies and supply chains are so interconnected, actions taken in one location \u2014 such as unsustainable resource extraction, poor labour practices, or high emissions \u2014 can have significant social, economic or environmental consequences elsewhere in the interconnected global system, creating a shared need for sustainable, responsible practices.', misconception: 'Sustainability challenges are sometimes framed as purely local or national issues, when the interconnected nature of global trade and TNC operations means that sustainable development genuinely requires coordinated, international approaches.', tag: 'The need for sustainable development' },
    { q: 'A recognised limitation of relying on voluntary CSR commitments (rather than binding international law) is that they:', options: ['They are so strict that companies leave developing countries', 'Commitments vary in ambition and delivery because they are not legally required', 'They are enforced by the UN, which limits company flexibility, with fines for breaking them', 'They apply only to companies based in the EU'], correct: 1, explain: 'A recognised limitation of voluntary CSR commitments is that, because they are not legally mandated in the same binding way as national or international law, they can vary significantly in ambition and genuine implementation between different companies, making outcomes less consistent than a legally enforced standard would be.', misconception: 'CSR commitments are sometimes assumed to carry the same binding force as law, when their voluntary nature means genuine implementation and ambition can vary considerably between companies, which is an important point to raise in a balanced evaluation.', tag: 'Evaluating CSR' },
    { q: 'Compared to voluntary CSR commitments, International Framework Agreements (IFAs) are generally considered to offer:', options: ['Legally binding rules enforced by national courts in every country, with fines for any violation', 'A negotiated commitment involving unions, giving a stronger basis for standards', 'A weaker commitment, as unions have no role in drafting them', 'The same protection as a voluntary company code of conduct'], correct: 1, explain: 'Compared to purely voluntary, unilateral CSR commitments, IFAs are generally considered to offer a more formally negotiated commitment, often involving trade unions as a negotiating partner, which can provide a somewhat stronger and more accountable basis for consistent labour standards across a TNC\u2019s international operations.', misconception: 'IFAs and general CSR statements are sometimes treated as equivalent, when the negotiated, agreement-based nature of an IFA (typically involving a union partner) distinguishes it from a company unilaterally announcing its own voluntary CSR policy.', tag: 'International Framework Agreements' },
    { q: 'When evaluating IKEA\u2019s sustainability initiatives as an example of TNC CSR, a balanced response would consider:', options: ['Mainly IKEA\u2019s own sustainability reports, as they contain the best data', 'Real progress, alongside questions about pace, scale and verification', 'Mainly the targets IKEA has set, since targets show commitment', 'Mainly how cheap IKEA\u2019s products are for consumers'], correct: 1, explain: 'A balanced evaluation of IKEA\u2019s sustainability initiatives considers both the genuine, specific progress made (such as sourcing and energy targets) and legitimate questions worth raising about the pace, scale, and independent verification of these commitments relative to the company\u2019s overall global environmental and social footprint.', misconception: 'Evaluations of TNC sustainability claims sometimes fall into an all-positive or all-negative extreme, when geographers are expected to weigh up genuine progress alongside legitimate critical questions about scale and verification.', tag: 'IKEA and sustainability' },
    { q: 'The relationship between global interdependence, TNCs, and sustainable development illustrates that:', options: ['National governments alone can deliver sustainable development, without any role for TNCs', 'As supply chains interconnect, CSR and IFAs matter more for sustainability', 'Interdependence reduces the need for TNCs to act responsibly', 'IFAs have replaced the need for CSR in most TNCs'], correct: 1, explain: 'This lesson illustrates that as TNCs and global supply chains become more interconnected through growing global interdependence, tools such as CSR practices and formally negotiated agreements like IFAs become increasingly significant mechanisms for pursuing sustainable development at a genuinely global scale, extending beyond what any single national government could achieve alone.', misconception: 'Sustainable development is sometimes considered purely a matter of national government policy, when the interconnected, global nature of TNC operations means that corporate-level mechanisms like CSR and IFAs also play a genuinely significant role.', tag: 'The need for sustainable development' }
  ]
};

window.SBL_LESSONS['HD-t2-l1-culture'] = {
  id: 'HD-t2-l1-culture',
  topicNumber: 2,
  topicTitle: 'Changing identities and cultures',
  title: 'Culture, ethnicity and identity',
  href: '/geography/paper-2/hl-2/t2-changing/l1-culture',
  syllabusFocus: 'The global spectrum of cultural traits, ethnicities and identities, and ways in which the spectrum of diversity is widening or narrowing at different scales, using terminology including culture, expression of culture, cultural trait, ethnicity, cultural differentialism, indigenous, cultural hybridisation, cultural homogenisation/convergence, cultural dilution, westernisation, homogenisation of landscapes, cultural imperialism/imposition, and detraditionalisation.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is culture?', request: 'Define culture, cultural traits, and the expression of culture' },
    { label: 'Ethnicity vs culture', request: 'Explain the difference between ethnicity and culture' },
    { label: 'Cultural differentialism', request: 'Explain what cultural differentialism means' },
    { label: 'Homogenisation vs hybridisation', request: 'Explain the difference between cultural homogenisation and cultural hybridisation' },
    { label: 'Westernisation and cultural imperialism', request: 'Explain westernisation and cultural imperialism' },
    { label: 'The global spectrum of culture', request: 'Explain what is meant by the global spectrum of culture, and how it can widen or narrow' },
    { label: 'Help with local examples', request: 'Give me examples of a global culture at both a global and local scale, such as at an international school' }
  ],
  checklist: [
    'I can use a wide range of terminology related to culture, ethnicity and diversity.',
    'I can identify the aspects of a \u2018global culture\u2019, on a global scale and a local scale.',
    'I can describe ethnic diversity in a place and comment on how this reflects a spectrum of diversity.'
  ],
  readinessQuestions: [
    'What is the difference between culture and ethnicity?',
    'What is a cultural trait, and can you give an example?',
    'What is the difference between cultural homogenisation and cultural hybridisation?',
    'What does westernisation mean?',
    'What does it mean to say the "spectrum of diversity" is widening or narrowing at different scales?'
  ],
  quiz: [
    { q: 'Culture is best defined as:', options: ['The ancestry and nationality that a group of people share, passed down through generations', 'The shared beliefs, values, customs, behaviours and artefacts of a group', 'The official language and religion of a country', 'The art, music and literature produced by a society'], correct: 1, explain: 'Culture refers to the shared beliefs, values, customs, behaviours and artefacts (such as food, clothing, art and traditions) that characterise a particular group of people.', misconception: 'Culture is sometimes reduced to a single element like language or food, when it is a broad concept encompassing many shared aspects of a group\u2019s way of life.', tag: 'What is culture?' },
    { q: 'A cultural trait is best described as:', options: ['The whole set of beliefs and values shared by a group, including religion and language', 'A single element of a culture, such as a style of dress, food or custom', 'A group\u2019s shared ancestry or heritage', 'The way a culture changes over time'], correct: 1, explain: 'A cultural trait is a single, specific element of a culture \u2014 such as a particular style of dress, a food dish, a custom, or a form of music \u2014 rather than the entire culture as a whole.', misconception: 'A cultural trait is sometimes confused with an entire culture; it specifically refers to one identifiable component within a broader culture.', tag: 'What is culture?' },
    { q: 'Ethnicity differs from culture mainly because it:', options: ['Refers to beliefs and customs that are learned rather than inherited', 'Often refers to shared ancestry, heritage or nationality', 'Is defined by the country in which a person lives', 'Refers only to a person\u2019s religion'], correct: 1, explain: 'Ethnicity typically refers to a group sharing a common ancestry, heritage or national origin, which is related to but distinct from culture \u2014 members of the same ethnic group may share cultural traits, but ethnicity is more specifically about shared heritage and identity.', misconception: 'Culture and ethnicity are sometimes used interchangeably, but ethnicity is more specifically tied to shared ancestry/heritage, while culture is the broader set of shared practices and values.', tag: 'Ethnicity vs culture' },
    { q: 'Cultural differentialism refers to:', options: ['Cultures blending together to create new, mixed forms, as communities adopt global brands', 'Distinct cultural identities being maintained, resisting a single global culture', 'One dominant culture spreading and replacing others', 'Cultures becoming more similar through global media'], correct: 1, explain: 'Cultural differentialism refers to the view or process by which distinct cultural identities and differences are maintained and preserved, often as a response or resistance to the idea of a single, homogenised global culture.', misconception: 'Cultural differentialism is sometimes confused with homogenisation, which describes the opposite process; differentialism is specifically about the persistence of distinct cultural differences.', tag: 'Cultural differentialism' },
    { q: 'Cultural homogenisation (or convergence) refers to:', options: ['Cultures becoming more similar, often through a dominant global culture', 'Cultures staying distinct as they resist outside influence, as people protect local traditions', 'Two cultures blending to form a new culture', 'Traditional customs declining within one community'], correct: 0, explain: 'Cultural homogenisation, also called cultural convergence, describes the process by which cultures become increasingly similar to one another, often through the widespread influence of a dominant global culture, such as through media, brands or consumer products.', misconception: 'Homogenisation is sometimes confused with hybridisation; homogenisation specifically describes cultures becoming more similar/uniform, whereas hybridisation describes cultures blending to create something new.', tag: 'Homogenisation vs hybridisation' },
    { q: 'Cultural hybridisation refers to:', options: ['One culture completely replacing another, so that no trace of the original culture remains', 'The blending of two or more cultures to create a new, mixed form', 'Cultures becoming identical around the world', 'A culture rejecting outside influences'], correct: 1, explain: 'Cultural hybridisation describes the blending of two or more cultures to create a new, mixed cultural form \u2014 for example, fusion cuisine or music genres that combine elements from different cultural traditions.', misconception: 'Hybridisation is sometimes confused with one culture simply dominating or replacing another; hybridisation specifically describes a genuine blending that creates something new from multiple cultural influences.', tag: 'Homogenisation vs hybridisation' },
    { q: 'Westernisation refers to:', options: ['The spread of any cultural trait from one country to another, wherever that trait originated', 'The adoption of values and practices from Western societies by other cultures', 'The adaptation of global brands to local tastes', 'Western societies adopting traits from other cultures'], correct: 1, explain: 'Westernisation describes the adoption of cultural traits, values and practices associated with Western societies \u2014 particularly North American and European culture \u2014 by other cultures around the world, often linked to globalisation and media influence.', misconception: 'Westernisation is sometimes used as a general synonym for "modernisation," when it specifically refers to the spread of culturally Western traits and values, not simply economic or technological development in general.', tag: 'Westernisation and cultural imperialism' },
    { q: 'Cultural imperialism (or cultural imposition) refers to:', options: ['The equal exchange of cultural traits between countries, so that both sides benefit equally', 'One culture dominating or being imposed on another, linked to unequal power', 'The blending of cultures to create something new', 'A culture deliberately protecting its traditions'], correct: 1, explain: 'Cultural imperialism (or cultural imposition) refers to the dominance or imposition of one culture\u2019s values and practices over another, often linked to unequal power relationships, such as the global economic or media influence of powerful countries or corporations over less powerful ones.', misconception: 'Cultural imperialism is sometimes assumed to only occur through direct historical colonisation, when it can also occur through more subtle modern mechanisms, such as global media and consumer brand influence, still rooted in unequal power relationships.', tag: 'Westernisation and cultural imperialism' },
    { q: 'Detraditionalisation refers to:', options: ['The revival of traditional customs as a reaction to globalisation', 'The declining influence of traditional customs and beliefs', 'The blending of traditional and modern practices', 'The spread of traditional customs to other countries'], correct: 1, explain: 'Detraditionalisation describes a decline in the influence and practice of traditional customs, beliefs, and practices within a society, often associated with the pressures and influences of modernisation and globalisation.', misconception: 'Detraditionalisation is sometimes assumed to mean traditions completely disappear, when it more accurately describes a general decline in their influence and prevalence, which can occur to varying degrees.', tag: 'The global spectrum of culture' },
    { q: 'The "global spectrum of culture" widening or narrowing at different scales illustrates that:', options: ['Diversity is narrowing at the same rate everywhere, as global brands reach every community', 'The balance between diversity and convergence varies between places and scales', 'Diversity widens at the global scale but never locally', 'Cultural change is driven mainly by government policy'], correct: 1, explain: 'The idea of the spectrum widening or narrowing at different scales illustrates that the balance between cultural diversity (differentialism) and cultural convergence (homogenisation) can vary significantly between different places and scales \u2014 a local community (such as an international school) might show a very different pattern of cultural diversity compared to an entire nation or the world as a whole.', misconception: 'Cultural change is sometimes assumed to happen uniformly and identically everywhere, when the reality is that patterns of diversity, homogenisation and hybridisation can look quite different depending on the specific scale and place being examined.', tag: 'The global spectrum of culture' }
  ]
};

window.SBL_LESSONS['HD-t2-l2-the-effects-of'] = {
  id: 'HD-t2-l2-the-effects-of',
  topicNumber: 2,
  topicTitle: 'Changing identities and cultures',
  title: 'The effects of global interactions on cultural diversity',
  href: '/geography/paper-2/hl-2/t2-changing/l2-the-effects-of',
  syllabusFocus: 'The effects of global interactions on cultural diversity in different places: the diffusion of cultural traits and cultural imperialism; glocalization of branded commodities and cultural hybridity; and cultural landscape changes in the built environment, using the example of Dubai.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'Diffusion of cultural traits', request: 'Explain how cultural traits diffuse and spread between places' },
    { label: 'Glocalisation', request: 'Explain what glocalisation is, using branded commodities as an example' },
    { label: 'Glocalisation as cultural imperialism', request: 'Explain how glocalisation can be seen as an example of cultural imperialism' },
    { label: 'Cultural landscape change', request: 'Explain how global interactions can change the cultural landscape of the built environment' },
    { label: 'The Dubai case study', request: 'Teach me the Dubai case study on cultural landscape change and homogenisation' },
    { label: 'Comparing cultural traits', request: 'Compare specific cultural traits with those associated with a global culture' },
    { label: 'Evaluating cultural change', request: 'Help me evaluate the positive and negative effects of global interactions on cultural diversity' }
  ],
  checklist: [
    'I can describe how glocalisation can be seen as an example of cultural imperialism.',
    'I can identify specific cultural traits and compare these with those traits associated with a global culture.',
    'I can describe how Dubai is an example where the homogenisation of landscape has occurred, especially in the built environment.'
  ],
  ibQuestions: [
    {
      question: "\u201cCultural changes caused by globalisation have affected urban and rural places equally.\u201d Discuss this statement. [May 2021, Paper 3, Q2(b)]",
      marks: 16,
      markScheme: "A strong response discusses cultural changes (diffusion of global brands, media, language and diet, cultural hybridity, loss of traditions) and compares urban places (connected, multicultural, diaspora communities) with rural places (more isolated, but reached by the internet, migration and tourism), considering resistance and change over time, and reaches a justified conclusion. Mark holistically out of 16: reward a balanced, critical discussion of different perspectives, detailed named examples and a well-supported conclusion."
    }
  ],
  readinessQuestions: [
    'How do cultural traits diffuse between places?',
    'What is glocalisation, and can you give an example?',
    'How can glocalisation be seen as a form of cultural imperialism, even though it appears to adapt to local cultures?',
    'How has Dubai\u2019s built environment reflected the homogenisation of landscapes?',
    'What is one positive and one negative effect of global interactions on cultural diversity?'
  ],
  quiz: [
    { q: 'The diffusion of cultural traits refers to:', options: ['The blending of two cultures into a new form, such as fusion food or music', 'The spread of cultural traits, such as food or fashion, between places', 'The loss of traditional customs in one place', 'The deliberate protection of a culture from outside influence'], correct: 1, explain: 'The diffusion of cultural traits describes the spread of cultural elements, such as food, fashion, music or media, from their place of origin to other places over time, often accelerated by global interactions like trade, migration and communication technology.', misconception: 'Cultural traits are sometimes assumed to stay fixed in their place of origin, when the process of diffusion means many cultural traits become widely adopted far beyond where they first developed.', tag: 'Diffusion of cultural traits' },
    { q: 'Glocalisation refers to:', options: ['Local businesses expanding to sell their products globally, such as Thai restaurants abroad', 'Global brands adapting products to local tastes and preferences', 'Global brands selling identical products in every country', 'Governments limiting global brands to protect local culture'], correct: 1, explain: 'Glocalisation describes the process by which global brands or products are adapted to fit local cultural tastes and preferences in different markets, combining "global" and "local" \u2014 for example, a global fast food chain adjusting its menu to suit local cuisine in different countries.', misconception: 'Glocalisation is sometimes assumed to mean a product is fully "localised" with no remaining global influence, when it specifically describes a blend \u2014 a globally standardised brand making local adaptations, rather than becoming a genuinely local product.', tag: 'Glocalisation' },
    { q: 'Glocalisation can be seen as an example of cultural imperialism because:', options: ['It forces local businesses to copy foreign products exactly', 'It still spreads a foreign, often Western, brand into local markets', 'It replaces local tastes with identical global products, so local tastes disappear', 'It is usually imposed by foreign governments'], correct: 1, explain: 'Glocalisation can be seen as a form of cultural imperialism because, even while making surface-level adaptations to local tastes, the underlying strategy still represents the continued global expansion and commercial dominance of a foreign (often Western) brand into local markets and cultural spaces, extending its influence rather than genuinely ceding ground to local alternatives.', misconception: 'Glocalisation is sometimes seen as a purely respectful, culturally sensitive strategy with no power dynamic involved, when a critical geographical perspective recognises it can still represent a form of cultural imperialism, using local adaptation as a means of continued global market expansion.', tag: 'Glocalisation as cultural imperialism' },
    { q: 'Cultural hybridity, in the context of glocalisation, describes:', options: ['A local product being exported unchanged', 'The blending of global and local elements to create a new product or form', 'A global product replacing a local one', 'Two local traditions merging within one country, such as a Thai dish served in Bangkok'], correct: 1, explain: 'Cultural hybridity in this context describes the blending of global and local cultural elements to create a new, hybrid product or cultural form \u2014 such as a global fast food chain\u2019s menu incorporating genuinely local ingredients or dishes alongside its standard global offerings.', misconception: 'Hybridity is sometimes confused with simple product variation; genuine cultural hybridity involves a real blending of distinct cultural elements, not just minor cosmetic differences between markets.', tag: 'Glocalisation' },
    { q: 'Cultural landscape change in the built environment refers to:', options: ['Changes to natural landscapes caused by global trade, such as deforestation for plantations', 'Changes to buildings and urban design that reflect changing cultural influences', 'Population growth in cities due to migration', 'The conservation of historic buildings'], correct: 1, explain: 'Cultural landscape change in the built environment refers to changes in human-made structures, architecture and urban design that reflect shifting cultural influences, often driven or accelerated by global interactions such as international investment, tourism, and the influence of global architectural styles and brands.', misconception: 'Cultural landscape change is sometimes assumed to only relate to natural environments, when it specifically concerns human-made, built environments and how their design reflects (and sometimes homogenises) cultural influence.', tag: 'Cultural landscape change' },
    { q: 'Dubai is used as a case study of homogenisation in the built environment mainly because it:', options: ['Its traditional wind towers and souks dominate the city centre', 'Its skyline, malls and brands resemble those of other global cities', 'Its government bans foreign architecture in new buildings, to protect its Islamic identity', 'Its population is mainly Emirati, so it reflects local culture'], correct: 1, explain: 'Dubai is used as a case study because its rapid development has produced a skyline and built environment featuring many globally recognisable architectural styles, international luxury brands, and high-rise designs similar to patterns seen in other major global cities, illustrating how global investment and tourism can drive homogenisation of the urban landscape.', misconception: 'Dubai\u2019s built environment is sometimes assumed to be uniquely local in character, when a key geographical point of the case study is precisely how its rapid, internationally-driven development has produced landscape features closely mirroring other global cities, exemplifying homogenisation.', tag: 'The Dubai case study' },
    { q: 'A driver behind Dubai\u2019s cultural landscape change has been:', options: ['Rapid growth of the local Emirati population', 'International investment, tourism and a strategy to become a global hub', 'Oil wealth spent mainly on preserving historic districts, such as the Al Fahidi district', 'Migration from Europe making up most of the population'], correct: 1, explain: 'A key driver behind Dubai\u2019s cultural landscape change has been significant international investment, tourism development, and a deliberate government strategy to position the city as a global business and luxury tourism hub, attracting international architecture, brands and investment that have reshaped its built environment.', misconception: 'Rapid urban transformation like Dubai\u2019s is sometimes seen as accidental or organic, when it specifically reflects a deliberate development strategy aimed at attracting global investment and establishing international prominence.', tag: 'The Dubai case study' },
    { q: 'A specific cultural trait (such as a traditional local dish or clothing style) differs from traits associated with a "global culture" because:', options: ['Local traits are always older, while global traits are invented by TNCs', 'Local traits are rooted in a place and its history; global traits are consumed widely', 'Local traits spread faster because they are more authentic, so they will replace global traits', 'Global traits only exist in high-income countries'], correct: 1, explain: 'Specific cultural traits are typically rooted in and closely associated with a particular local place and history (such as a traditional dish or clothing style unique to one region), while traits associated with a "global culture" (like certain international brands, media franchises or consumer products) are widely recognised and consumed across many different, often unrelated, places.', misconception: 'It is sometimes assumed there is no meaningful distinction between "local" and "global" cultural traits, when comparing specific, place-rooted traits against widely recognised global culture traits is a useful way to understand the tension between cultural diversity and homogenisation.', tag: 'Comparing cultural traits' },
    { q: 'A potential positive effect of global interactions on cultural diversity is that they can:', options: ['Guarantee that traditional cultures are protected from change, so people keep their traditional customs', 'Introduce new influences and hybrid forms that can enrich local culture', 'Reduce migration, which keeps cultures distinct', 'Make all cultures more similar, which reduces conflict'], correct: 1, explain: 'A recognised positive effect of global interactions is that they can introduce new cultural influences, ideas, and hybrid cultural forms that can enrich and diversify a local culture (such as new cuisines, music genres or artistic styles), even while there remain genuine risks of homogenisation and cultural imperialism to weigh against these benefits.', misconception: 'Global interactions\u2019 effect on culture is sometimes presented as entirely negative (homogenisation/imperialism) or entirely positive (enrichment/hybridity); a balanced evaluation recognises that both genuine benefits and risks exist simultaneously.', tag: 'Evaluating cultural change' },
    { q: 'When evaluating the overall effects of global interactions on cultural diversity, a strong geographical response would:', options: ['Focus on Dubai, as it shows the effects that occur everywhere, so other examples are not needed', 'Weigh benefits and risks, recognising that effects vary between places and scales', 'Argue that homogenisation always outweighs hybridity', 'Concentrate on global brands, as they cause most cultural change'], correct: 1, explain: 'A strong evaluative response considers how the effects of global interactions on cultural diversity can vary significantly between different places and scales, weighing genuine benefits (such as cultural hybridity and enriching cultural exchange) against genuine risks (such as homogenisation and cultural imperialism), and grounding this in real-world evidence such as glocalisation strategies or the Dubai case study.', misconception: 'Evaluation is sometimes reduced to picking one single, universal conclusion, when geographers are expected to show how outcomes can genuinely vary by place and scale, supported by specific case study evidence.', tag: 'Evaluating cultural change' }
  ]
};

window.SBL_LESSONS['HD-t2-l3-how-diasporas'] = {
  id: 'HD-t2-l3-how-diasporas',
  topicNumber: 2,
  topicTitle: 'Changing identities and cultures',
  title: 'How diasporas influence cultural diversity and identity \u2014 Chinatown in London',
  href: '/geography/paper-2/hl-2/t2-changing/l3-how-diasporas',
  syllabusFocus: 'How diasporas influence cultural diversity and identity at both global and local scales, including a case study of a global diaspora population and its cultures, such as the Chinese diaspora.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is a diaspora?', request: 'Define diaspora and explain the role of diasporas in maintaining a culture abroad' },
    { label: 'The Chinese diaspora worldwide', request: 'Describe the presence of Chinese diasporas worldwide' },
    { label: 'Chinese diaspora case study', request: 'Summarise the importance of a specific Chinese diaspora community, such as in San Francisco or London' },
    { label: 'Diasporas at global and local scales', request: 'Explain how diasporas influence cultural diversity and identity at both global and local scales' },
    { label: 'Diaspora communities and identity', request: 'Explain how diaspora communities help maintain a sense of cultural identity abroad' },
    { label: 'Applying the IB essay mark scheme', request: 'Help me apply the IB essay mark scheme to a question about diasporas, using the Chinese diaspora as an example' },
    { label: 'Help me structure an essay', request: 'Help me plan an essay answer on the topic of diasporas' }
  ],
  checklist: [
    'I can define and explain the role of diasporas in maintaining a culture abroad.',
    'I can describe the presence of Chinese diasporas worldwide and summarise the importance of a specific Chinese diaspora community.',
    'I can apply the IB essay mark scheme to an answer on the topic of diasporas.'
  ],
  readinessQuestions: [
    'What is a diaspora, in your own words?',
    'How do diaspora communities help maintain a culture abroad?',
    'Where are some significant Chinese diaspora communities found around the world?',
    'What makes a specific Chinese diaspora community, such as in San Francisco, significant?',
    'How do diasporas influence cultural diversity at both a global and local scale?'
  ],
  quiz: [
    { q: 'A diaspora is best defined as:', options: ['Any group of temporary migrants working abroad, such as seasonal farm workers who return home', 'A population that has dispersed from its homeland but keeps cultural ties to it', 'A minority group living in its own homeland', 'People who have fully assimilated into a new country'], correct: 1, explain: 'A diaspora refers to a population of people who have dispersed from their original homeland to live in other parts of the world, often while maintaining cultural, social or emotional connections to their place and culture of origin.', misconception: 'A diaspora is sometimes confused with migration in general; a diaspora specifically refers to the resulting dispersed population and its ongoing cultural connections, not simply the act of moving.', tag: 'What is a diaspora?' },
    { q: 'Diaspora communities help maintain a culture abroad partly by:', options: ['Assimilating fully so that children adopt the host culture, losing their language within one generation', 'Setting up cultural institutions, businesses, places of worship and networks', 'Living separately and avoiding contact with the host population', 'Returning home regularly instead of building communities abroad'], correct: 1, explain: 'Diaspora communities often help maintain a culture abroad by establishing cultural institutions, businesses, places of worship, and community networks that help preserve and pass on cultural traditions, language and practices in their new location.', misconception: 'Diaspora communities are sometimes assumed to simply assimilate completely, losing connection to their culture of origin, when many diaspora communities actively work to preserve and pass on cultural practices across generations.', tag: 'What is a diaspora?' },
    { q: 'Chinese diaspora communities are found:', options: ['Mainly in Europe, because of colonial links with Britain, which has the largest Chinatown outside Asia', 'In large numbers worldwide, especially in Southeast Asia, North America and Europe', 'Mainly in Africa, due to Chinese investment projects', 'Mainly in North America, where most migrated in the 1800s'], correct: 1, explain: 'Chinese diaspora communities are found in significant numbers across many countries and cities worldwide, including major concentrations in North America, Europe, and throughout Southeast Asia, reflecting centuries of migration.', misconception: 'The scale and global reach of the Chinese diaspora is sometimes underestimated; it represents one of the largest and most geographically widespread diaspora populations in the world.', tag: 'The Chinese diaspora worldwide' },
    { q: 'A "Chinatown" district in a city such as San Francisco or London is significant because it:', options: ['It is where most of the city\u2019s Chinese population lives today, after people moved out of the suburbs', 'It is where Chinese culture, businesses and institutions are most visible', 'It was created by city planners as a tourist attraction', 'It is the same in every city, with no local variation'], correct: 1, explain: 'A "Chinatown" district represents a concentrated area within a city where Chinese diaspora culture, businesses (such as restaurants and shops), and community institutions are particularly visible and established, often serving as both a cultural hub for the diaspora community and a point of interaction with the wider host city population.', misconception: 'Chinatown districts are sometimes viewed only as tourist attractions, when they represent genuine, functioning centres of diaspora community life, culture and identity, even while also serving a role in the wider city\u2019s cultural landscape.', tag: 'Chinese diaspora case study' },
    { q: 'A Chinese diaspora community in a city like San Francisco illustrates the influence of diasporas at which scale(s)?', options: ['Only the local scale, as each Chinatown is independent, because each neighbourhood has its own history', 'Both local (the neighbourhood) and global (a worldwide network)', 'Only the global scale, through remittances to China', 'Only the national scale, through government policy'], correct: 1, explain: 'A Chinese diaspora community in a specific city like San Francisco illustrates diaspora influence at both scales simultaneously: a clear local-scale influence on that specific neighbourhood and city, and a connection to a much wider global-scale Chinese diaspora network spanning many countries.', misconception: 'Diaspora influence is sometimes considered only at a single scale, when a genuinely strong geographical answer recognises how the same diaspora community operates and has influence at both local and global scales simultaneously.', tag: 'Diasporas at global and local scales' },
    { q: 'Diaspora communities can influence cultural diversity in their host country by:', options: ['Replacing the host country\u2019s culture in the areas where they settle, so the original culture there disappears', 'Introducing new traits, such as food and festivals, that become part of host culture', 'Only affecting cultural diversity within their own community', 'Reducing diversity by encouraging assimilation'], correct: 1, explain: 'Diaspora communities can influence cultural diversity in their host country by introducing new cultural traits, such as cuisine, festivals and traditions, which can become recognised and adopted as part of the host country\u2019s broader cultural diversity, sometimes leading to genuine cultural hybridity over time.', misconception: 'The cultural influence of diaspora communities on their host country is sometimes overlooked, when specific diaspora contributions (such as widely enjoyed cuisines originating from diaspora communities) demonstrate a genuine, lasting effect on host country cultural diversity.', tag: 'Diaspora communities and identity' },
    { q: 'When writing an IB-style essay on the topic of diasporas, a strong response would typically need to:', options: ['Describe the diaspora in as much detail as possible, including its full migration history', 'Use named case studies, apply terminology and address the command term', 'Focus on one argument without considering counterpoints', 'Use general examples so the answer applies anywhere'], correct: 1, explain: 'A strong IB-style essay response on diasporas would typically need to use specific case study evidence (such as a named diaspora community and location), apply relevant geographical terminology accurately, and directly address the specific command term of the question (such as "evaluate," "discuss," or "examine").', misconception: 'Essay responses are sometimes written as a general description with no specific evidence, when the IB mark scheme specifically rewards responses that combine accurate terminology, named case study evidence, and a direct response to the command term used in the question.', tag: 'Applying the IB essay mark scheme' },
    { q: 'The IB essay mark scheme for a question on diasporas would generally reward a response that:', options: ['A long answer covering as many diasporas as possible, with a separate paragraph for each one', 'Accurate knowledge applied to named examples with a clear argument', 'A detailed description of one diaspora\u2019s history', 'Lists of facts organised under clear headings'], correct: 1, explain: 'The IB essay mark scheme generally rewards a response that demonstrates accurate knowledge of the topic, applies that knowledge specifically to named case study evidence (rather than staying vague or general), and develops a clear line of reasoning or argument that directly addresses the question asked.', misconception: 'It is sometimes assumed simply including more content automatically earns more marks, when the mark scheme specifically rewards precision, accurate application of evidence, and clear reasoning, rather than volume alone.', tag: 'Applying the IB essay mark scheme' },
    { q: 'A useful essay-writing strategy when discussing a diaspora case study, such as the Chinese diaspora in San Francisco, is to:', options: ['Mention as many cities with Chinatowns as possible, to show the global reach of the diaspora', 'Include specific details on scale, history, institutions and influence', 'Focus on the history of migration rather than the present', 'Use statistics only, as they are the strongest evidence'], correct: 1, explain: 'A useful essay-writing strategy is to include specific, accurate details about the named case study community \u2014 such as its scale, history, key cultural institutions, and specific influence on the local area \u2014 to demonstrate genuine case study knowledge rather than a generic, unsupported answer.', misconception: 'Simply naming a place is sometimes assumed to be sufficient case study evidence, when genuinely strong essay responses go further by including specific, accurate supporting detail about that named example.', tag: 'Chinese diaspora case study' },
    { q: 'Overall, studying diasporas like the Chinese diaspora helps geographers understand:', options: ['Why migrants usually return home within a generation, once they have saved enough money', 'How migration shapes identity and diversity at local and global scales over time', 'Why diasporas eventually lose all ties to their homeland', 'How governments control where migrants settle'], correct: 1, explain: 'Studying diasporas like the Chinese diaspora helps geographers understand how migration and ongoing cultural connection across borders can shape identity and cultural diversity at both local and global scales, often continuing to have significant cultural influence long after the initial migration took place, sometimes across multiple generations.', misconception: 'Diaspora communities are sometimes considered a purely historical topic, when their ongoing cultural influence and evolving identity remain a genuinely current and significant area of study in human geography.', tag: 'Diasporas at global and local scales' }
  ]
};

window.SBL_LESSONS['HD-t3-l1-local-and-civil'] = {
  id: 'HD-t3-l1-local-and-civil',
  topicNumber: 3,
  topicTitle: 'Local responses to global interactions',
  title: 'Local and civil society resistance to global interactions',
  href: '/geography/paper-2/hl-2/t3-local-responses/l1-local-and-civil',
  syllabusFocus: 'Local and civil society resistance to global interactions: rejection of globalized production, including campaigns against TNCs and in favour of local sourcing of food and goods by citizens (such as Greenpeace campaigns against Asia Pulp and Paper and the ramin paper trail, and Thailand\u2019s \u2018Eat Local\u2019 movement); and the rise of anti-immigration movements (such as the Minutemen border patrol in the US).',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'What is anti-globalisation resistance?', request: 'Explain what is meant by local and civil society resistance to global interactions' },
    { label: 'Asia Pulp and Paper campaign', request: 'Explain what Asia Pulp and Paper (APP) is and summarise the Greenpeace campaign against the company' },
    { label: 'The ramin paper trail campaign', request: 'Explain the ramin paper trail environmental issue and summarise the Greenpeace campaign' },
    { label: 'The anti-Starbucks movement', request: 'Explain the opposition to Starbucks in terms of globalisation and global interactions' },
    { label: '\u2018Eat Local\u2019 in Thailand', request: 'Summarise the reasons for the \u2018Eat Local\u2019 movement at a national level in Thailand' },
    { label: 'Anti-immigration movements', request: 'Explain the rise of anti-immigration movements, such as the Minutemen border patrol in the US' },
    { label: 'Evaluating civil resistance movements', request: 'Help me evaluate the usefulness of civil movements as a form of resistance to globalisation' }
  ],
  checklist: [
    'I can identify how the ways in which the anti-globalisation movement can be manifested.',
    'I can describe the opposition to Starbucks in terms of globalisation and global interactions.',
    'I can summarise the reasons for the \u2018Eat Local\u2019 movement at a national level (Thailand).',
    'I can evaluate the usefulness of civil movements, with particular reference to the Minutemen border patrol in the US.'
  ],
  readinessQuestions: [
    'What is Asia Pulp and Paper, and what environmental concerns have been raised about the company?',
    'What was the ramin paper trail campaign, and what did Greenpeace achieve?',
    'Why has there been opposition to Starbucks in some places?',
    'Why do some people in Thailand favour eating and buying more locally produced food?',
    'What is the Minutemen border patrol, and how does it relate to anti-immigration movements in the US?'
  ],
  quiz: [
    { q: 'Local and civil society resistance to global interactions can be understood as:', options: ['Government policies that restrict trade and migration, such as tariffs and travel bans', 'Ways people and organisations push back against aspects of globalisation', 'International agreements that regulate TNCs', 'Global brands adapting their products to local markets'], correct: 1, explain: 'Local and civil society resistance to global interactions refers to the various ways individuals, communities and organisations push back against or resist aspects of globalisation, such as campaigning against TNCs, favouring local production, or opposing immigration, often motivated by environmental, economic, cultural or social concerns.', misconception: 'Resistance to globalisation is sometimes assumed to be a single, uniform movement, when it actually takes many different forms depending on the specific concern (environmental, economic, cultural) and the actors involved.', tag: 'What is anti-globalisation resistance?' },
    { q: 'Asia Pulp and Paper (APP) is a company that has faced environmental campaigns primarily because of concerns relating to:', options: ['Air pollution from its paper mills in China', 'Deforestation linked to pulp and paper production in Indonesia', 'Poor working conditions in its garment factories in Bangladesh', 'Overfishing by its shipping fleet in the Pacific'], correct: 1, explain: 'Asia Pulp and Paper (APP), a major paper and pulp producer operating primarily in Indonesia, has faced significant environmental campaigns due to concerns about deforestation and unsustainable logging practices linked to its production, threatening rainforest habitats and biodiversity.', misconception: 'Large TNCs in the paper/pulp industry are sometimes assumed to have no significant environmental footprint, when companies like APP have specifically faced major campaigns due to documented deforestation concerns.', tag: 'Asia Pulp and Paper campaign' },
    { q: 'Greenpeace\u2019s campaign against Asia Pulp and Paper primarily aimed to:', options: ['Persuade the Indonesian government to nationalise APP, so profits stay within the country', 'Pressure APP and its customers to change sourcing and stop deforestation', 'Organise a worldwide boycott of all paper products', 'Take APP to the International Court of Justice'], correct: 1, explain: 'Greenpeace\u2019s campaign against Asia Pulp and Paper primarily aimed to raise public awareness of the company\u2019s deforestation practices and pressure both the company and its business customers (such as major global brands) to change sourcing practices and reduce associated deforestation.', misconception: 'Environmental campaigns against TNCs are sometimes assumed to target only the company directly, when campaigns like this one also strategically target the company\u2019s customers and business partners to create wider commercial pressure for change.', tag: 'Asia Pulp and Paper campaign' },
    { q: 'The "ramin paper trail" campaign specifically focused on:', options: ['Tracking illegal palm oil exports from Malaysia to Europe, through the Strait of Malacca', 'Tracing illegally logged ramin, a protected hardwood, to consumer products', 'Mapping the spread of haze from burning ramin forests', 'Recording waste paper exported from Europe to Asia'], correct: 1, explain: 'The "ramin paper trail" campaign specifically focused on tracing the illegal logging and trade of ramin, a protected tropical hardwood species, through international supply chains to expose how it was ending up in consumer products, despite legal protections.', misconception: 'Environmental supply chain campaigns are sometimes seen as vague or symbolic, when campaigns like the ramin paper trail specifically involved detailed tracing of a protected species through real supply chains to demonstrate illegal trade.', tag: 'The ramin paper trail campaign' },
    { q: 'A notable success or outcome associated with campaigns like the ramin paper trail has been:', options: ['An international ban on all trade in tropical hardwoods, agreed by ASEAN governments', 'Raising awareness and increasing pressure for supply-chain transparency', 'The closure of APP\u2019s operations in Indonesia', 'An end to illegal logging across Southeast Asia'], correct: 1, explain: 'A notable outcome of campaigns like the ramin paper trail has been raising public and corporate awareness of illegal logging supply chains, contributing to broader pressure on companies and governments for greater supply chain transparency and accountability regarding the sourcing of forest products.', misconception: 'Environmental campaigns are sometimes assumed to have no measurable real-world effect, when raising awareness and shifting corporate/consumer pressure on supply chain practices is itself a recognised and meaningful form of campaign success.', tag: 'The ramin paper trail campaign' },
    { q: 'Opposition to Starbucks, in the context of globalisation and global interactions, has often centred on concerns that the company:', options: ['Pays coffee farmers less than any other coffee chain, which reduces their incomes', 'Represents a large TNC displacing local, independent coffee shops', 'Uses only coffee grown in its home country', 'Refuses to adapt its menu to local tastes'], correct: 1, explain: 'Opposition to Starbucks has often centred on concerns that the company represents the global expansion and commercial dominance of a large TNC, with critics arguing this can displace local, independently owned coffee shops and businesses, and contribute to the broader homogenisation of local high streets and consumer culture.', misconception: 'Opposition to large global brands like Starbucks is sometimes seen as purely about product quality, when the underlying geographical concern in this context is specifically about the broader effects of TNC expansion on local businesses and cultural/economic diversity.', tag: 'The anti-Starbucks movement' },
    { q: 'The \u2018Eat Local\u2019 movement in Thailand (particularly in Bangkok) has been driven by a combination of factors including:', options: ['Mainly government food-safety rules', 'Social, economic and environmental factors', 'Mainly lower prices than imported food, as Thai food is cheaper in markets', 'Mainly tourist demand for Thai food'], correct: 1, explain: 'The \u2018Eat Local\u2019 movement in Thailand has been driven by a combination of social factors (supporting local communities and food traditions), economic factors (supporting local farmers and producers rather than global supply chains), and environmental factors (reducing the environmental footprint associated with long-distance food transport).', misconception: '\u2018Eat Local\u2019 movements are sometimes assumed to be driven by a single motivation (often assumed to be purely environmental), when in reality they typically combine social, economic and environmental reasoning together.', tag: '\u2018Eat Local\u2019 in Thailand' },
    { q: 'The \u2018Eat Local\u2019 movement represents a form of opposition to globalisation because it:', options: ['Promotes Thai food exports to global markets', 'Favours local food over global supply chains', 'Supports Thai restaurant chains expanding abroad', 'Bans foreign food chains from Bangkok'], correct: 1, explain: 'The \u2018Eat Local\u2019 movement represents a form of opposition to globalisation because it deliberately favours locally produced food and goods over globally sourced alternatives, reflecting a conscious preference for supporting local economic and cultural connections rather than relying on globalised supply chains.', misconception: 'Consumer movements like \u2018Eat Local\u2019 are sometimes viewed as unrelated to globalisation debates, when they represent a genuinely deliberate, everyday form of resistance to globalised food systems and production.', tag: '\u2018Eat Local\u2019 in Thailand' },
    { q: 'The rise of anti-immigration movements, such as the Minutemen border patrol in the US, can be understood as:', options: ['An official US government border protection agency, set up after the 2001 attacks', 'Civil society resistance to migration, linked to identity, jobs and security', 'A campaign by employers for more migrant workers', 'A movement opposing TNCs rather than migration'], correct: 1, explain: 'The rise of anti-immigration movements, such as the Minutemen border patrol (a volunteer civilian group that monitored the US-Mexico border), can be understood as a form of civil society resistance to increased global migration flows, often motivated by concerns about national identity, economic competition for jobs, or border security.', misconception: 'The Minutemen are sometimes assumed to be an official government agency, when they were specifically a volunteer, non-governmental civilian group, illustrating civil society (rather than state) resistance to immigration.', tag: 'Anti-immigration movements' },
    { q: 'When evaluating the usefulness of civil society movements as a form of resistance to globalisation, geographers would consider that they can:', options: ['Usually succeed, because governments must follow public opinion, especially in democratic countries', 'Raise awareness and sometimes change policy, though effectiveness varies', 'Rarely have any effect, because TNCs ignore them', 'Always promote international-mindedness'], correct: 1, explain: 'A balanced evaluation of civil society movements (from environmental campaigns like the ramin paper trail, to anti-Starbucks or Eat Local movements, to anti-immigration groups like the Minutemen) recognises that such movements can effectively raise public awareness and sometimes influence corporate or government policy, though their overall effectiveness, methods, and legitimacy can vary considerably and generate genuine debate depending on the specific movement in question.', misconception: 'Civil society movements are sometimes evaluated as uniformly positive or uniformly ineffective, when a genuinely strong evaluation recognises that different movements vary significantly in their methods, legitimacy, and effectiveness, and can generate real debate.', tag: 'Evaluating civil resistance movements' }
  ]
};

window.SBL_LESSONS['HD-t3-l2-geopolitical'] = {
  id: 'HD-t3-l2-geopolitical',
  topicNumber: 3,
  topicTitle: 'Local responses to global interactions',
  title: 'Geopolitical constraints on global interactions',
  href: '/geography/paper-2/hl-2/t3-local-responses/l2-geopolitical',
  syllabusFocus: 'Geopolitical constraints on global interactions: government and militia controls on personal freedoms to participate in global interactions, and national trade restrictions, including protectionism and resource nationalism.',
  starterButtons: [
    { label: 'Teach me this lesson', request: 'Give me a full overview of this lesson' },
    { label: 'Government controls on freedoms', request: 'Explain how governments can restrict personal freedoms to participate in global interactions' },
    { label: 'US Executive Order 13769', request: 'Summarise how a government policy such as Executive Order 13769 has reduced global interactions' },
    { label: 'Comparing internet restrictions', request: 'Compare how internet restrictions vary between different countries worldwide' },
    { label: 'What is protectionism?', request: 'Explain what protectionism is and how it can be implemented' },
    { label: 'What is resource nationalism?', request: 'Explain what resource nationalism is' },
    { label: 'Protectionism at different levels', request: 'Explain how protectionism can be implemented at different levels and why' },
    { label: 'Evaluating geopolitical constraints', request: 'Help me evaluate the effects of geopolitical constraints on global interactions' }
  ],
  checklist: [
    'I can summarise how a government policy has reduced global interactions.',
    'I can compare the levels of internet restrictions between different countries worldwide.',
    'I can explain how protectionism can be implemented at different levels and why.'
  ],
  readinessQuestions: [
    'How can governments restrict personal freedoms to participate in global interactions?',
    'What is one example of a government policy that has reduced global interactions?',
    'Why do internet restrictions vary between different countries?',
    'What is protectionism, and what forms can it take?',
    'What is resource nationalism?'
  ],
  quiz: [
    { q: 'Geopolitical constraints on global interactions refer to:', options: ['Physical barriers such as mountains, oceans and deserts, which limit how far people can travel', 'Restrictions by governments or militias on the movement of people, goods or information', 'Limits caused by the cost of transport and communication', 'Restrictions imposed by TNCs on their own supply chains'], correct: 1, explain: 'Geopolitical constraints refer to government, political or militia-imposed restrictions \u2014 such as travel bans, internet censorship, or trade barriers \u2014 that limit the ability of people, goods, capital, or information to move and interact globally.', misconception: 'Geopolitical constraints are sometimes confused with purely physical barriers to interaction (like oceans); geopolitical constraints specifically arise from political decisions and policy, not physical geography.', tag: 'Government controls on freedoms' },
    { q: 'Government travel or immigration bans, such as restrictions targeting specific countries, represent a geopolitical constraint because they:', options: ['Mainly limit the flow of goods and capital, rather than people', 'Directly restrict the movement of people between countries', 'Only affect tourists, not migrants or students', 'Encourage migration to neighbouring countries'], correct: 1, explain: 'Government travel or immigration bans directly restrict the movement of people between countries, limiting global interaction through reduced migration, travel, and disrupted family, business or educational connections between affected countries and populations.', misconception: 'Immigration policy is sometimes considered purely a domestic matter, when travel/immigration restrictions have a direct and measurable effect on the level of global interaction between the restricting country and the affected populations.', tag: 'US Executive Order 13769' },
    { q: 'A specific government policy example (such as a travel ban executive order) reducing global interactions would typically involve:', options: ['Placing tariffs on goods imported from named countries, to protect domestic jobs', 'Restricting entry for citizens of specific named countries', 'Closing the border to every foreign national', 'Blocking access to foreign websites'], correct: 1, explain: 'A specific policy example, such as a travel ban executive order, typically involves restricting entry into a country for citizens of specific named countries, directly reducing travel, migration and associated global interactions between the restricting country and those specifically targeted nations.', misconception: 'Government restrictions are sometimes assumed to apply universally to all countries equally, when many real-world examples specifically target selected countries, creating uneven patterns of restricted global interaction.', tag: 'US Executive Order 13769' },
    { q: 'Internet restrictions vary significantly between different countries worldwide partly because:', options: ['Internet access depends only on a country\u2019s wealth, so poorer countries always have more control', 'Governments differ in control, access and surveillance, reflecting political systems', 'Restrictions are set by global tech companies, not governments', 'All restrictions are agreed through the United Nations'], correct: 1, explain: 'Internet restrictions vary significantly between countries because governments differ considerably in the level of control they exert over online content, access to specific websites or platforms, and levels of digital surveillance, often reflecting differing political systems, priorities, and attitudes towards free information flow.', misconception: 'Internet access and freedom is sometimes assumed to be relatively uniform worldwide, when significant variation exists between countries in terms of government-imposed restrictions and censorship of online global interaction.', tag: 'Comparing internet restrictions' },
    { q: 'A country with significant internet restrictions compared to one with minimal restrictions would typically show:', options: ['Faster internet speeds because there is less traffic, as fewer people are online at once', 'Reduced access to global websites, platforms and information', 'Greater use of global social media platforms', 'The same access, because restrictions are easy to avoid'], correct: 1, explain: 'A country with significant internet restrictions would typically show a reduced ability for citizens to access certain global websites, social media platforms, or information sources compared to a country with minimal restrictions, limiting citizens\u2019 participation in certain forms of global digital interaction and information exchange.', misconception: 'It is sometimes assumed internet restrictions have only a minor practical effect, when significant restrictions can substantially limit citizens\u2019 genuine ability to participate in global digital communication, information access and online commerce.', tag: 'Comparing internet restrictions' },
    { q: 'Protectionism, as an economic policy, refers to:', options: ['Policies that remove barriers to trade between countries, through free trade agreements and blocs', 'Policies restricting trade to protect domestic industries, such as tariffs and quotas', 'Government control over a country\u2019s natural resources', 'Laws protecting intellectual property such as patents'], correct: 1, explain: 'Protectionism refers to government policies designed to restrict international trade in order to protect domestic industries from foreign competition, commonly implemented through tools such as tariffs (taxes on imports), quotas (limits on import quantities), or subsidies for domestic producers.', misconception: 'Protectionism is sometimes confused with free trade policy; protectionism specifically involves deliberate government intervention to restrict trade and shield domestic industries, the opposite of an open trade approach.', tag: 'What is protectionism?' },
    { q: 'Resource nationalism refers to:', options: ['Selling state-owned resources to foreign investors, to attract investment into extraction', 'Increased state control over natural resources, limiting foreign ownership', 'Protecting domestic industries with import tariffs', 'Using natural resources to generate renewable energy'], correct: 1, explain: 'Resource nationalism refers to a government policy tendency to assert increased state control over a country\u2019s natural resources (such as oil, gas or minerals), often by limiting foreign ownership or investment in resource extraction, or by increasing state involvement and revenue capture from these industries.', misconception: 'Resource nationalism is sometimes confused with simple environmental protection policy; it specifically concerns increased state/national control and ownership over resource extraction, which can be motivated by economic or political goals rather than purely environmental ones.', tag: 'What is resource nationalism?' },
    { q: 'Protectionism can be implemented at different levels, such as:', options: ['Only through complete bans on all imports, which stop all foreign competition', 'National tariffs or targeted protection for strategic industries', 'Only through agreements made at the WTO', 'Only through military control of borders'], correct: 1, explain: 'Protectionism can be implemented at different levels and in different forms, ranging from broad national-level tariffs applied to a wide range of imported goods, to more targeted, industry-specific protections aimed at particular domestic sectors that a government considers strategically important to protect.', misconception: 'Protectionist policy is sometimes assumed to be a single, uniform approach, when governments can apply protectionism at varying scales and with varying degrees of targeting, from broad national tariffs to narrow, sector-specific measures.', tag: 'Protectionism at different levels' },
    { q: 'A government might choose to implement protectionist trade policy in order to:', options: ['Lower prices for domestic consumers, by making imports cheaper and more varied', 'Protect domestic jobs and strategic sectors, or respond to political pressure', 'Increase imports from trading partners', 'Meet WTO rules on free trade'], correct: 1, explain: 'A government might implement protectionist trade policy in order to protect domestic jobs and industries from foreign competition, support sectors considered strategically important (such as agriculture or defence-related industries), or respond to political pressure from domestic producers and workers.', misconception: 'Protectionist policy is sometimes assumed to have no clear rationale, when governments typically have specific economic or political motivations \u2014 job protection, strategic industry support, or domestic political pressure \u2014 behind such decisions.', tag: 'Protectionism at different levels' },
    { q: 'Overall, geopolitical constraints such as travel restrictions, internet censorship, protectionism, and resource nationalism illustrate that:', options: ['Globalisation always overcomes political barriers, as trade and technology always find a way round', 'Political decisions can limit or reshape global interactions', 'Constraints affect only authoritarian states', 'Physical barriers matter more than political ones'], correct: 1, explain: 'Taken together, geopolitical constraints such as travel restrictions, internet censorship, protectionism, and resource nationalism illustrate that government and political decisions can significantly limit or reshape the extent and nature of global interactions for a country and its citizens, even as broader globalisation trends continue in other parts of the world, showing that globalisation is not a simple, one-directional or universally applied process.', misconception: 'Globalisation is sometimes assumed to be a simple, uniformly increasing trend affecting every country equally, when geopolitical constraints demonstrate that governments retain significant power to selectively limit or reshape global interaction for their own populations.', tag: 'Government controls on freedoms' }
  ]
};

